B.az3=s(["\u092e\u0947\u0928\u0942 \u2630 \u203a \u092c\u093f\u0932 \u0938\u0947\u091f\u093f\u0902\u0917\u094d\u091c: \u092b\u0942\u0921 \u092a\u094d\u0932\u0947\u0938\u091a\u0947 \u0928\u093e\u0935, \u092a\u0924\u094d\u0924\u093e, \u092b\u094b\u0928, GSTIN, FSSAI, \u0916\u093e\u0932\u091a\u093e \u0938\u0902\u0926\u0947\u0936, \u0924\u0941\u092e\u091a\u093e UPI ID, \u0915\u0930, \u0936\u0941\u0932\u094d\u0915 \u0906\u0923\u093f \u0911\u092b\u0930 \u091f\u093e\u0915\u093e. \u0938\u0947\u0935\u094d\u0939 \u0926\u093e\u092c\u093e.","\u092e\u0947\u0928\u0942 \u2630 \u203a \u091f\u0947\u092c\u0932 \u0938\u0947\u091f\u0905\u092a: \u0935\u093f\u092d\u093e\u0917 (AC, \u0917\u093e\u0930\u094d\u0921\u0928\u2026) \u0906\u0923\u093f \u091f\u0947\u092c\u0932 (T1\u2013T10 \u0915\u093f\u0902\u0935\u093e A\u2013F) \u091c\u094b\u0921\u093e.","\u092e\u0947\u0928\u0942 \u2630 \u203a \u092e\u0947\u0928\u0942: \u0906\u0927\u0940 \u0936\u094d\u0930\u0947\u0923\u0940, \u092e\u0917 \u0939\u093e\u092b / \u092b\u0941\u0932 \u0915\u093f\u0902\u092e\u0924 \u0906\u0923\u093f \u0936\u093e\u0915\u093e\u0939\u093e\u0930\u0940 / \u092e\u093e\u0902\u0938\u093e\u0939\u093e\u0930\u0940 \u0916\u0942\u0923 \u0905\u0938\u0932\u0947\u0932\u0947 \u0906\u092f\u091f\u092e \u091c\u094b\u0921\u093e.","\u092e\u0947\u0928\u0942 \u2630 \u203a \u0915\u0930\u094d\u092e\u091a\u093e\u0930\u0940: \u092e\u0945\u0928\u0947\u091c\u0930, \u0915\u0945\u092a\u094d\u091f\u0928 / \u0935\u0947\u091f\u0930, \u0915\u093f\u091a\u0928 \u0906\u0923\u093f \u0915\u0945\u0936\u093f\u092f\u0930 \u092f\u093e\u0902\u091a\u093e \u092e\u094b\u092c\u093e\u0908\u0932 \u0928\u0902\u092c\u0930 \u0935 \u096c \u0905\u0902\u0915\u0940 \u092a\u093f\u0928 \u091f\u093e\u0915\u0942\u0928 \u091c\u094b\u0921\u093e.","\u092e\u0947\u0928\u0942 \u2630 \u203a \u092a\u0930\u0935\u093e\u0928\u0917\u094d\u092f\u093e: \u092a\u094d\u0930\u0924\u094d\u092f\u0947\u0915 \u092d\u0942\u092e\u093f\u0915\u0947\u0932\u093e \u0915\u093e\u092f \u0915\u0930\u0924\u093e \u092f\u0947\u0908\u0932 \u0924\u0947 \u091a\u093e\u0932\u0942 / \u092c\u0902\u0926 \u0915\u0930\u093e.","\u0911\u092b\u0930 \u0915\u093f\u0902\u092e\u0924: \u092e\u0947\u0928\u0942 \u203a \u0906\u092f\u091f\u092e\u0935\u0930 \u091f\u0945\u092a \u0915\u0930\u093e \u203a \u0911\u092b\u0930 \u0915\u093f\u0902\u092e\u0924 \u091a\u093e\u0932\u0942 \u0915\u0930\u093e, \u0915\u092e\u0940 \u0915\u093f\u0902\u092e\u0924 \u0935 (\u0910\u091a\u094d\u091b\u093f\u0915) \u0936\u0947\u0935\u091f\u091a\u0940 \u0924\u093e\u0930\u0940\u0916 \u091f\u093e\u0915\u093e. \u092e\u0947\u0928\u0942\u0924 \u091c\u0941\u0928\u0940 \u0915\u093f\u0902\u092e\u0924 \u0916\u094b\u0921\u0932\u0947\u0932\u0940 \u0926\u093f\u0938\u0924\u0947.","\u0938\u0947\u091f\u093f\u0902\u0917\u094d\u091c: \u092a\u094d\u0930\u0924\u094d\u092f\u0947\u0915 \u092b\u094b\u0928\u0935\u0930 \u0925\u0940\u092e \u0930\u0902\u0917 (\u0915\u0947\u0936\u0930\u0940, \u0928\u093f\u0933\u093e, \u0939\u093f\u0930\u0935\u093e\u2026) \u0906\u0923\u093f \u092d\u093e\u0937\u093e (English, \u0939\u093f\u0902\u0926\u0940, \u092e\u0930\u093e\u0920\u0940) \u0928\u093f\u0935\u0921\u093e."],t.s)
B.bqz=new A.a5("\u0938\u0941\u0930\u0941\u0935\u093e\u0924 (\u092e\u093e\u0932\u0915)",B.az3)
B.b4I=s(["\u0915\u0930\u094d\u092e\u091a\u093e\u0931\u094d\u092f\u093e\u091a\u094d\u092f\u093e \u092b\u094b\u0928\u0935\u0930 \u0939\u0947\u091a Yora \u0972\u092a \u091f\u093e\u0915\u093e \u0906\u0923\u093f \u0924\u094d\u092f\u093e\u0902\u091a\u094d\u092f\u093e \u092e\u094b\u092c\u093e\u0908\u0932 \u0928\u0902\u092c\u0930 \u0935 \u092a\u093f\u0928\u0928\u0947 \u0932\u0949\u0917\u093f\u0928 \u0915\u0930\u093e.",'\u092a\u0941\u0922\u091a\u094d\u092f\u093e \u0935\u0947\u0933\u0940 \u092b\u093f\u0902\u0917\u0930\u092a\u094d\u0930\u093f\u0902\u091f\u0938\u093e\u0920\u0940 "\u0939\u094b\u092f" \u0926\u093e\u092c\u093e.',"\u092a\u093f\u0928 \u0935\u093f\u0938\u0930\u0932\u093e? \u092e\u093e\u0932\u0915: \u0915\u0930\u094d\u092e\u091a\u093e\u0930\u0940 \u203a \u22ee \u203a \u092a\u093f\u0928 \u0930\u0940\u0938\u0947\u091f. \u0915\u0930\u094d\u092e\u091a\u093e\u0930\u0940 \u0915\u093e\u092e \u0938\u094b\u0921\u0942\u0928 \u0917\u0947\u0932\u093e? \u0924\u094d\u092f\u093e\u0932\u093e \u092c\u0902\u0926 \u0915\u0930\u093e."],t.s)
B.bpR=new A.a5("\u0915\u0930\u094d\u092e\u091a\u093e\u0930\u0940 \u0932\u0949\u0917\u093f\u0928",B.b4I)
B.b5J=s(["\u0921\u093e\u0907\u0928-\u0907\u0928 \u092e\u0927\u094d\u092f\u0947 \u0938\u0930\u094d\u0935 \u091f\u0947\u092c\u0932 \u0926\u093f\u0938\u0924\u093e\u0924: \u0939\u093f\u0930\u0935\u093e = \u092e\u094b\u0915\u0933\u093e, \u092a\u093f\u0935\u0933\u093e = \u092d\u0930\u0932\u0947\u0932\u093e, \u0928\u093f\u0933\u093e = \u092c\u093f\u0932 \u092a\u094d\u0930\u093f\u0902\u091f \u091d\u093e\u0932\u0947.","\u091f\u0947\u092c\u0932\u0935\u0930 \u091f\u0945\u092a \u0915\u0930\u093e \u203a \u0906\u092f\u091f\u092e \u0928\u093f\u0935\u0921\u093e (\u0939\u093e\u092b / \u092b\u0941\u0932) \u203a \u0915\u093f\u091a\u0928\u0938\u093e\u0920\u0940 \u091f\u0940\u092a \u0926\u094d\u092f\u093e\u092f\u091a\u0940 \u0905\u0938\u0932\u094d\u092f\u093e\u0938 \u0906\u092f\u091f\u092e\u0935\u0930 \u091f\u0945\u092a \u0915\u0930\u093e \u203a \u0915\u093f\u091a\u0928\u0932\u093e \u092a\u093e\u0920\u0935\u093e. KOT \u0924\u092f\u093e\u0930 \u0939\u094b\u0924\u094b.","\u0928\u0902\u0924\u0930 \u0906\u0923\u0916\u0940 \u0906\u092f\u091f\u092e? \u091c\u094b\u0921\u093e \u0906\u0923\u093f \u092a\u0941\u0928\u094d\u0939\u093e \u092a\u093e\u0920\u0935\u093e \u2014 \u092b\u0915\u094d\u0924 \u0928\u0935\u0940\u0928 \u0906\u092f\u091f\u092e \u0915\u093f\u091a\u0928\u0932\u093e \u091c\u093e\u0924\u093e\u0924.",'\u091c\u0947\u0935\u0923 \u0924\u092f\u093e\u0930 \u091d\u093e\u0932\u0947 \u0915\u0940 \u092b\u094b\u0928 \u0935\u094d\u0939\u093e\u092f\u092c\u094d\u0930\u0947\u091f \u0939\u094b\u0924\u094b \u0906\u0923\u093f "\u091f\u0947\u092c\u0932 \u2026 \u0924\u092f\u093e\u0930 \u0906\u0939\u0947" \u0926\u093f\u0938\u0924\u0947. \u0935\u093e\u0922\u093e \u0906\u0923\u093f "\u0926\u093f\u0932\u0947 \u0905\u0938\u0947 \u092e\u093e\u0930\u094d\u0915 \u0915\u0930\u093e" \u0926\u093e\u092c\u093e.',"\u091a\u0941\u0915\u0940\u091a\u093e \u0906\u092f\u091f\u092e? \u0924\u094d\u092f\u093e\u0935\u0930 \u2715 \u0926\u093e\u092c\u093e \u0906\u0923\u093f \u0915\u093e\u0930\u0923 \u0926\u094d\u092f\u093e. \u091f\u0947\u092c\u0932 \u0939\u0932\u0935\u0923\u0947 / \u091c\u094b\u0921\u0923\u0947 \u22ee \u092e\u0947\u0928\u0942\u092e\u0927\u0942\u0928."],t.s)
